head.script:
scwin.screenId = "jldods70301";

///////// 1. 변수 및 선언 영역 /////////

scwin.fold = $c.util.getComponent('fold');


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_ReportData.get("total")) + "건 [" + String(dma_ReportData.get("currentPage")) + "/" + String(dma_ReportData.get("endListPage")) + " 페이지]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_goSearchReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fnCheckList('type');
        scwin.fnCheckList('class');
        scwin.fold.setStyle("display", "none");
        (($c.util.getComponent('foldBt')) && ($c.util.getComponent('foldBt')).addClass ? ($c.util.getComponent('foldBt')).addClass('on') : console.error('[sdd] addClass 미지원 컴포넌트: foldBt'));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70301.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_goSearch();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description fold 을(를) 보이기를 바꾼다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70301.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

