/**
 * @event
 * @name scwin.grd_ReportDataList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_ReportDataList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (typeof scwin.previewPopOpen === 'function') { scwin.previewPopOpen(r["formCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.previewPopOpen (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.previewPopOpen'); } return; } 
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goSearch = async function () {
    const sbmOptions = {
        id: "tx_goSearch",
        method: "post",
        action: "/discls/form.do",
        ref: "dma_goSearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70301.tx_goSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_88").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.grd_ReportDataList_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_ReportDataList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.fillAct' });
    }
};

/**
 * @method
 * @name scwin.enterSearchForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.enterSearchForm = async function () {
    /* sdd-asis-lifecycle:begin enterSearchForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.goSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearch = async function () {
    /* sdd-asis-lifecycle:begin goSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!scwin.isCheckSelect('type')) {
        await alertE('담당기관을 선택하십시오.');
        return;
    }
    if (!scwin.isCheckSelect('class')) {
        await alertE('공시구분을 선택하십시오.');
        return;
    }
    blockLoading();
    const foldYn = $('#foldBt').hasClass('on') === true ? "Y" : "N";
    $c.util.getComponent('dma_goSearchReq').set('foldYn', foldYn);
    $c.util.getComponent('dma_goSearchReq').set('method', "formReport");
    (document.frmReportSearch || { elements: [] }).action = "/discls/form.do";
    await scwin.tx_goSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isCheckSelect
 * @author Inswave
 * @date 2026. 09. 29
 * @param checkType
 * @returns
 * @hidden N
*/
scwin.isCheckSelect = function (checkType) {
    /* sdd-asis-lifecycle:begin isCheckSelect — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (checkType === "type") {
        if (((!$c.util.getComponent('ipt_allType') || typeof $c.util.getComponent('ipt_allType').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_allType'), false) : ($c.util.getComponent('ipt_allType').getValue() != null && String($c.util.getComponent('ipt_allType').getValue()) !== '')) === true) {
            return true;
        }
        for (var i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            if ((String($c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue() || '') !== '') === true) {
                return true;
            }
        }
    } else {
        if (checkType === "class") {
            if (((!$c.util.getComponent('ipt_allClass') || typeof $c.util.getComponent('ipt_allClass').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_allClass'), false) : ($c.util.getComponent('ipt_allClass').getValue() != null && String($c.util.getComponent('ipt_allClass').getValue()) !== '')) === true) {
                return true;
            }
            for (var i = 0; i < $c.util.getComponent('dlt_ReportClass').getTotalRow(); i++) {
                if ((['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_ReportClass').getCellData(i, 'sprtBzDtlId'))) >= 0)=== true) {
                    return true;
                }
            }
        }
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCheckAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param checkType
 * @returns
 * @hidden N
*/
scwin.fnCheckAll = function (checkType) {
    /* sdd-asis-lifecycle:begin fnCheckAll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (checkType === "type") {
        for (var i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            $c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).checked = (String($c.util.getComponent('ipt_allType').getValue() || "") !== "");
        }
    } else {
        if (checkType === "class") {
            for (var i = 0; i < $c.util.getComponent('dlt_ReportClass').getTotalRow(); i++) {
                $c.util.getComponent('dlt_ReportClass').setCellData(i, 'sprtBzDtlId', (((String($c.util.getComponent('ipt_allClass').getValue() || "") !== "")) ? 'true' : 'false'));
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCheckList
 * @author Inswave
 * @date 2026. 09. 29
 * @param checkType
 * @returns
 * @hidden N
*/
scwin.fnCheckList = function (checkType) {
    /* sdd-asis-lifecycle:begin fnCheckList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let all_checked = true;
    if (checkType === "type") {
        for (var i = 0; i < $c.util.getComponent('ipt_checkType').length; i++) {
            var prefix = $c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue();
            if (!(String($c.util.getComponent(["ipt_checkType", "ipt_checkType_2", "ipt_checkType_3"][i]).getValue() || '') !== '')) {
                all_checked = false;
            }
        }
        $c.util.getComponent("ipt_allType").setValue(all_checked);
    } else {
        if (checkType === "class") {
            for (var i = 0; i < $c.util.getComponent('dlt_ReportClass').getTotalRow(); i++) {
                var prefix = $c.util.getComponent('dlt_ReportClass').getCellData(i, 'sprtBzDtlId');
                if (!(['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_ReportClass').getCellData(i, 'sprtBzDtlId'))) >= 0)) {
                    all_checked = false;
                }
            }
            $c.util.getComponent("ipt_allClass").setValue(all_checked);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }


/**
 * @event
 * @name scwin.krxpage_pagenavigator_88_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_88_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_goSearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_88.page' }); } scwin.tx_goSearch(); };
